    86  /// MCInst - Instances of this class represent a single low-level machine
    87  /// instruction.
    88  struct MCInst {
    89          unsigned OpcodePub;
    90          uint8_t size;   // number of operands
    91          bool has_imm;   // indicate this instruction has an X86_OP_IMM operand - used for ATT syntax
    92          uint8_t op1_size; // size of 1st operand - for X86 Intel syntax
    93          unsigned Opcode;
    94          MCOperand Operands[48];
    95          cs_insn *flat_insn;     // insn to be exposed to public
    96          uint64_t address;       // address of this insn
    97          cs_struct *csh; // save the main csh
    98          uint8_t x86opsize;      // opsize for [mem] operand
    99
   100          // These flags could be used to pass some info from one target subcomponent
   101          // to another, for example, from disassembler to asm printer. The values of
   102          // the flags have any sense on target level only (e.g. prefixes on x86).
   103          unsigned flags;
   104
   105          // (Optional) instruction prefix, which can be up to 4 bytes.
   106          // A prefix byte gets value 0 when irrelevant.
   107          // This is copied from cs_x86 struct
   108          uint8_t x86_prefix[4];
   109          uint8_t imm_size;       // immediate size for X86_OP_IMM operand
   110          bool writeback; // writeback for ARM
   111          // operand access index for list of registers sharing the same access right (for ARM)
   112          uint8_t ac_idx;
   113          uint8_t popcode_adjust;   // Pseudo X86 instruction adjust
   114          char assembly[8];       // for special instruction, so that we dont need printer
   115          unsigned char evm_data[32];     // for EVM PUSH operand
   116          cs_wasm_op wasm_data;    // for WASM operand
   117  };
